/* Put training limits next to the console, where people choose what to practise. */
const consolePanel=document.querySelector('.console');if(consolePanel){const unavailable=[...consolePanel.querySelectorAll('button:disabled')].filter(b=>b.textContent.trim());const p=document.createElement('p');p.className='profile-scope';p.textContent=unavailable.length?'Training configuration · '+unavailable.length+' labelled hardware controls are not modelled.':'Training configuration · hardware setup and installation options differ by rink.';const link=document.createElement('a');link.href='#controller-reference';link.textContent='Supported functions & limits ↓';link.onclick=()=>{document.getElementById('controller-reference').open=true;};p.append(link);document.querySelector('.console-viewport').before(p);}
